import React from "react";

export default function ListofPlayers({ players }) {
  return (
    <div>
      {players.map((item, i) => (
        <div key={i}>
          <li>
            Mr. {item.name} <span>{item.score}</span>
          </li>
        </div>
      ))}
    </div>
  );
}
